// Package noexit forbids direct calls to os.Exit in the main function of package main.
//
// The analyzer recognizes calls using regular, aliased, and dot imports of os,
// as well as calls with parentheses around the function name. It also checks
// calls within conditionals, loops, defer statements, and go statements.
//
// Nested function bodies, other functions, and methods are not checked.
// Synthetic test main packages generated by Go are skipped.
// Indirect calls through variables or helper functions are not tracked.
// Type information identifies the target function, so functions with the same
// name in other packages and shadowed identifiers are not mistaken for os.Exit.
package noexit

import (
	"go/ast"
	"go/types"
	"strings"

	"golang.org/x/tools/go/analysis"
)

// Analyzer reports direct calls to os.Exit in the main function of package main
// without inspecting nested function bodies. It can be used with go/analysis
// drivers, including multichecker. The analyzer produces no analysis result
// and offers no suggested fixes.
var Analyzer = &analysis.Analyzer{
	Name: "noexit",
	Doc:  "forbid direct calls to os.Exit in main.main",
	Run:  run,
}

// run traverses main function bodies in package main and reports calls to os.Exit.
// Other packages are skipped. Both the result and error are always nil;
// diagnostics are emitted through pass.Reportf.
func run(pass *analysis.Pass) (any, error) {
	if pass.Pkg.Name() != "main" {
		return nil, nil
	}
	// Go generates a main package with this suffix to run package tests.
	// Its os.Exit(m.Run()) call is not application code.
	if strings.HasSuffix(pass.Pkg.Path(), ".test") {
		return nil, nil
	}

	for _, file := range pass.Files {
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Name.Name != "main" || fn.Recv != nil || fn.Body == nil {
				continue
			}

			ast.Inspect(fn.Body, func(node ast.Node) bool {
				if _, ok := node.(*ast.FuncLit); ok {
					return false
				}
				call, ok := node.(*ast.CallExpr)
				if !ok {
					return true
				}

				// Unwrap parentheses to also recognize (os.Exit)(1).
				callee := call.Fun
				for {
					paren, isParen := callee.(*ast.ParenExpr)
					if !isParen {
						break
					}
					callee = paren.X
				}

				var ident *ast.Ident
				switch expr := callee.(type) {
				case *ast.SelectorExpr:
					ident = expr.Sel
				case *ast.Ident:
					ident = expr
				default:
					return true
				}

				// Use the function object rather than the import name to handle
				// aliases, dot imports, and shadowing of os.
				obj, ok := pass.TypesInfo.Uses[ident].(*types.Func)
				if ok && obj.Pkg() != nil && obj.Pkg().Path() == "os" && obj.Name() == "Exit" {
					pass.Reportf(call.Pos(), "direct call to os.Exit in main.main is forbidden")
				}
				return true
			})
		}
	}
	return nil, nil
}
